void unit_test_deleteNode_key_not_found_left_subtree(void) {
    // Setup: Build a BST with values [10, 5, 15]
    int values[] = {10, 5, 15};
    int size = 3;
    struct node* root = helper_build_tree(values, size);

    // Attempt to delete a key that is less than root->key and not present in the tree
    int key_to_delete = 2; // 2 < 10, not present, will traverse left and find NULL

    // Call function under test
    struct node* new_root = deleteNode(root, key_to_delete);

    // Expected inorder traversal is unchanged: [5, 10, 15]
    int expected_inorder[] = {5, 10, 15};
    helper_assert_tree_inorder(new_root, expected_inorder, size);

    // Expected node count is unchanged
    helper_assert_node_count(new_root, size);

    // Cleanup
    helper_cleanup_tree(new_root);
}
